/*
 * nav_aux.c -- nav-aux against the real AGC code (yaAGC oracle).
 *
 * Inputs and expected words: tools/oracle/cases/nav_aux.spec / .txt
 * (Comanche055) and nav_aux_lm.spec / .txt (Luminary099), generated by
 * tools/oracle/cases/gen/gen_nav_aux.py. Routines: LAT-LONG, LALOTORV,
 * RP-TO-R, R-TO-RP, TFFCONIC, TFFRP/RA, CALCTFF, LSPOS and LUNVEL (CM),
 * LSPOS (LM), INCORP2 (W update and state update).
 *
 * Tolerances (LSB of the AGC word): see docs/modules/oracle-cases.md.
 */
#include <stdio.h>

#include "agc/core/assert.h"
#include "agc/core/interp.h"
#include "agc/core/state.h"
#include "agc/nav/auxiliary.h"
#include "oracle_txt.h"

bool agc_assert_report(const char *file, int line, const char *expr)
{
    (void) printf("assert %s:%d %s\n", file, line, expr);

    return (false);
}

static agc_navaux_padload_t pad_of(const char *t)
{
    agc_navaux_padload_t pad;

    pad.tephem  = oracle_in_tp(t, "TEPHEM", 0);
    pad.azo     = oracle_in_dp(t, "AZO", 0);
    pad.axo     = oracle_in_dp(t, "AXO", 0);
    pad.neg_ayo = oracle_in_dp(t, "-AYO", 0);
    pad.lm504   = oracle_in_vec(t, "E4,1411"); /* 504LM */
    pad.rls     = oracle_in_vec(t, "RLS");

    return (pad);
}

static agc_latlong_opt_t opt_of(const char *t)
{
    agc_latlong_opt_t o;

    o.erad  = (oracle_in(t, "FLAGWRD1", 0) & 010000) != 0; /* ERADFLAG */
    o.lunar = (oracle_in(t, "FLAGWRD3", 0) & 04000) != 0;  /* LUNAFLAG */

    return (o);
}

/* ---- LAT-LONG / LALOTORV --------------------------------------------- */
static void latlong(const char *t, long tol)
{
    agc_interp_t               ip;
    agc_latlong_t              o;
    const agc_navaux_padload_t pad = pad_of(t);

    agc_interp_init(&ip);
    (void) agc_navaux_set_padload(&pad);
    (void) agc_latlong_from_r(&ip, &pad, opt_of(t),
                              oracle_in_vec(t, "ALPHAV"),
                              oracle_in_dp(t, "MPAC", 0), &o);
    oracle_require_ok(t, "POODOO");
    (void) oracle_cmp(t, "LAT", o.lat, oracle_out_dp(t, "LAT"), tol);
    (void) oracle_cmp(t, "LONG", o.lon, oracle_out_dp(t, "LONG"), tol);
    (void) oracle_cmp(t, "ALT", o.alt, oracle_out_dp(t, "ALT"), tol);
    (void) oracle_cmp(t, "ERADM", o.eradm, oracle_out_dp(t, "ERADM"), tol);
}

static void lalotorv(const char *t, long tol)
{
    agc_interp_t               ip;
    agc_latlong_t              in;
    agc_vec_t                  r;
    agc_dp_t                   eradm = 0;
    const agc_navaux_padload_t pad   = pad_of(t);

    agc_interp_init(&ip);
    (void) agc_navaux_set_padload(&pad);
    in.lat   = oracle_in_dp(t, "LAT", 0);
    in.lon   = oracle_in_dp(t, "LONG", 0);
    in.alt   = oracle_in_dp(t, "ALT", 0);
    in.eradm = 0;
    (void) agc_latlong_to_r(&ip, &pad, opt_of(t), &in,
                            oracle_in_dp(t, "MPAC", 0), &r, &eradm);
    oracle_require_ok(t, "POODOO");
    oracle_cmp_vec(t, "ALPHAV", r, oracle_out_vec(t, "ALPHAV"), tol);
    (void) oracle_cmp(t, "ERADM", eradm, oracle_out_dp(t, "ERADM"), tol);
}

/* ---- RP-TO-R / R-TO-RP ------------------------------------------------ */
static void rp_r(const char *t, bool to_r, long tol)
{
    agc_interp_t               ip;
    agc_vec_t                  out;
    const agc_navaux_padload_t pad  = pad_of(t);
    const bool                 moon = oracle_in(t, "MPAC", 0) != 0;
    const agc_vec_t            in   = oracle_in_vec(t, "VAC1");
    const agc_dp_t             tt   = oracle_in_dp(t, "VAC1+6", 0);

    agc_interp_init(&ip);
    (void) agc_navaux_set_padload(&pad);

    if (to_r)
    {
        (void) agc_planet_rp_to_r(&ip, &pad, moon, in, tt, &out);
    }
    else
    {
        (void) agc_planet_r_to_rp(&ip, &pad, moon, in, tt, &out);
    }

    oracle_require_ok(t, "POODOO");
    oracle_cmp_vec(t, "MPAC", out, oracle_out_mpac_vec(t), tol);
}

/* ---- TFF --------------------------------------------------------------- */
static void tff_conic_of(const char *conic_tag, agc_interp_t *ip,
                         agc_tff_t *tff)
{
    tff->rone = oracle_in_vec(conic_tag, "RONE");
    tff->vone = oracle_in_vec(conic_tag, "VONE");
    tff->rtmu = oracle_in_dp(conic_tag, "MPAC", 0);
    (void) agc_tff_conic(ip, tff);
}

static void tff(const char *base, long tol)
{
    char      tc[96];
    char      tr[96];
    char      tt[96];
    agc_tff_t f = {0};
    agc_tff_t g;
    agc_dp_t  tffv = 0;

    (void) snprintf(tc, sizeof tc, "%s_conic", base);
    (void) snprintf(tr, sizeof tr, "%s_rpra", base);
    (void) snprintf(tt, sizeof tt, "%s_calc", base);
    agc_interp_t ip;

    agc_interp_init(&ip);
    tff_conic_of(tc, &ip, &f);
    oracle_require_ok(tc, "POODOO");
    (void) oracle_cmp(tc, "RMAG1", f.rmag1, oracle_out_dp(tc, "VAC1+12"), tol);
    (void) oracle_cmp(tc, "TFFVSQ", f.tffvsq, oracle_out_dp(tc, "VAC1+20"),
                      tol);
    (void) oracle_cmp(tc, "TFF1/ALF", f.tff1_alf,
                      oracle_out_dp(tc, "VAC1+22"), tol);
    (void) oracle_cmp(tc, "TFFRTALF", f.tffrtalf,
                      oracle_out_dp(tc, "VAC1+24"), tol);
    (void) oracle_cmp(tc, "TFFALFA", f.tffalfa, oracle_out_dp(tc, "VAC1+26"),
                      tol);
    (void) oracle_cmp(tc, "TFFNP", f.tffnp, oracle_out_dp(tc, "VAC1+28"), tol);
    (void) oracle_cmp(tc, "TFF/RTMU", f.rtmu, oracle_out_dp(tc, "VAC1+30"), 0);
    (void) oracle_cmp(tc, "NRMAG", f.nrmag, oracle_out_dp(tc, "VAC1+32"), tol);
    (void) oracle_cmp(tc, "-NR (X1)", -f.nr, oracle_out_sp(tc, "VAC1+38"), 0);
    (void) oracle_cmp(tc, "-NA (X2)", -f.na, oracle_out_sp(tc, "VAC1+39"), 0);
    oracle_cmp_vec(tc, "VONE'", f.vone_p, oracle_out_vec(tc, "VONE'"), tol);

    g = f;
    (void) agc_tff_rp_ra(&ip, &g);
    oracle_require_ok(tr, "POODOO");
    (void) oracle_cmp(tr, "RPER", g.rper, oracle_out_dp(tr, "VAC1+14"), tol);
    (void) oracle_cmp(tr, "RAPO", g.rapo, oracle_out_dp(tr, "VAC1+16"), tol);

    g = f;
    (void) agc_tff_calctff(&ip, &g, oracle_in_dp(tt, "MPAC", 0), &tffv);
    oracle_require_ok(tt, "POODOO");
    (void) oracle_cmp(tt, "TFF", tffv, oracle_out_dp(tt, "MPAC"), 4);
    (void) oracle_cmp(tt, "TFFDELQ", g.tffdelq, oracle_out_dp(tt, "VAC1+10"),
                      tol);
    (void) oracle_cmp(tt, "TFFQ1", g.tffq1, oracle_out_dp(tt, "VAC1+14"), tol);
    (void) oracle_cmp(tt, "NRTERM", g.nrterm, oracle_out_dp(tt, "VAC1+16"),
                      tol);
    (void) oracle_cmp(tt, "RTERM", g.rterm, oracle_out_dp(tt, "VAC1+18"), 0);
    /* TFFX / TFFTEM are only written on the Z-series paths; elsewhere the
     * AGC leaves the push list as it was (the UNIT debris TFFCONIC left
     * there) and C leaves 0: compare only when the AGC wrote them.       */
    const agc_dp_t x_out = oracle_out_dp(tt, "VAC1+34");
    const agc_dp_t m_out = oracle_out_dp(tt, "VAC1+36");

    if (x_out != oracle_in_dp(tt, "VAC1", 34))
    {
        (void) oracle_cmp(tt, "TFFX", g.tffx, x_out, 32);
    }

    if (m_out != oracle_in_dp(tt, "VAC1", 36))
    {
        (void) oracle_cmp(tt, "TFFTEM", g.tfftem, m_out, tol);
    }
}

/* ---- LSPOS / LUNVEL ---------------------------------------------------- */
static agc_ephem_csm_t eph_of(const char *t)
{
    agc_ephem_csm_t e;

    e.timemo = oracle_in_tp(t, "TIMEMO", 0);

    for (int k = 0; k < AGC_EPHEM_NCOEF; k++)
    {
        e.vecoem[k] = oracle_in_vec_at(t, "VECOEM", k);
    }

    e.reso    = oracle_in_vec(t, "RESO");
    e.veso    = oracle_in_vec(t, "VESO");
    e.omegaes = oracle_in_dp(t, "OMEGAES", 0);

    return (e);
}

static void lspos_cm(const char *t, long tol)
{
    agc_interp_t          ip;
    agc_vec_t             moon;
    agc_vec_t             sun;
    const agc_ephem_csm_t e = eph_of(t);

    agc_interp_init(&ip);
    (void) agc_ephem_csm_lspos(&ip, &e, oracle_in_tp(t, "TEPHEM", 0),
                               oracle_in_dp(t, "MPAC", 0), &moon, &sun);
    oracle_require_ok(t, "POODOO");
    oracle_cmp_vec(t, "moon", moon, oracle_out_mpac_vec(t), tol);
    oracle_cmp_vec(t, "sun", sun, oracle_out_vec(t, "VAC1+2"), tol);
}

static void lunvel_cm(const char *t, long tol)
{
    agc_interp_t          ip;
    agc_vec_t             v;
    const agc_ephem_csm_t e = eph_of(t);

    agc_interp_init(&ip);
    (void) agc_ephem_csm_lunvel(&ip, &e, oracle_in_tp(t, "TEPHEM", 0),
                                oracle_in_dp(t, "MPAC", 0), &v);
    oracle_require_ok(t, "POODOO");
    oracle_cmp_vec(t, "vmoon", v, oracle_out_mpac_vec(t), tol);
}

static void lspos_lm(const char *t, long tol)
{
    agc_interp_t ip;
    agc_vec_t    vm;
    agc_vec_t    vs;

    agc_interp_init(&ip);
    (void) agc_ephem_lm_lspos(&ip, oracle_in_tp(t, "TEPHEM", 0),
                              oracle_in_dp(t, "MPAC", 0), &vm, &vs);
    oracle_require_ok(t, "POODOO");
    oracle_cmp_vec(t, "VMOON", vm, oracle_out_vec(t, "VMOON"), tol);
    oracle_cmp_vec(t, "VSUN", vs, oracle_out_vec(t, "VSUN"), tol);
}

/* ---- INCORP2 ----------------------------------------------------------- */
static void incorp2(const char *t, long tol_w, long tol_s)
{
    static agc_incorp_w_t w;
    agc_interp_t          ip;
    agc_incorp_t          inc = {0};
    agc_incorp_sv_t       sv  = {0};

    agc_interp_init(&ip);

    for (int k = 0; k < 3; k++)
    {
        inc.zi[k]     = oracle_in_vec_at(t, "ZI", k);
        inc.omega[k]  = oracle_in_vec_at(t, "OMEGA", k);
        inc.deltax[k] = oracle_in_vec_at(t, "DELTAX", k);
    }

    for (int k = 0; k < 27; k++)
    {
        w.blk[k / 9][k % 9] = oracle_in_vec_at(t, "W", k);
    }

    inc.gamma   = oracle_in_dp(t, "GAMMA", 0);
    inc.normgam = oracle_in(t, "NORMGAM", 0);
    inc.dim9    = (oracle_in(t, "FLAGWRD5", 0) & 00400) != 0; /* DMENFLG */
    sv.moon     = (oracle_in(t, "FLAGWRD8", 0) & 04000) != 0; /* CMOONFLG */
    sv.rcv      = oracle_in_vec(t, "RCVCSM");
    sv.vcv      = oracle_in_vec(t, "VCVCSM");
    sv.tdeltav  = oracle_in_vec(t, "DELTACSM");
    sv.tnuv     = oracle_in_vec(t, "NUVCSM");
    sv.x789     = oracle_in_vec(t, "X789");
    (void) agc_incorp_update_w(&ip, &inc, &w);
    (void) agc_incorp_update_state(&ip, &inc, &sv);
    oracle_require_ok(t, "INTWAKE");

    for (int k = 0; k < 27; k++)
    {
        char n[32];
        char what[32];

        (void) snprintf(n, sizeof n, "W+%d", 6 * k);
        (void) snprintf(what, sizeof what, "W[%d][%d]", k / 9, k % 9);
        oracle_cmp_vec(t, what, w.blk[k / 9][k % 9],
                       oracle_out_vec(t, (k == 0) ? "W" : n), tol_w);
    }

    oracle_cmp_vec(t, "TDELTAV", sv.tdeltav, oracle_out_vec(t, "TDELTAV"),
                   tol_s);
    oracle_cmp_vec(t, "TNUV", sv.tnuv, oracle_out_vec(t, "TNUV"), tol_s);
    oracle_cmp_vec(t, "RCV", sv.rcv, oracle_out_vec(t, "RCV"), 0);
    oracle_cmp_vec(t, "VCV", sv.vcv, oracle_out_vec(t, "VCV"), 0);

    if (inc.dim9)
    {
        oracle_cmp_vec(t, "X789", sv.x789, oracle_out_vec(t, "X789"), tol_s);
    }

    (void) oracle_cmp(t, "rectify", sv.rectify, 0, 0);
}

int main(void)
{
    if (!oracle_load("nav_aux"))
    {
        (void) printf("oracle_nav_aux: SKIP (case files not found)\n");

        return (0);
    }

    agc_state_init(AGC_VEHICLE_CSM);
    latlong("latlong_earth_fixed", 2);
    latlong("latlong_earth_ellip", 2);
    latlong("latlong_earth_south", 2);
    latlong("latlong_moon_rm", 256);
    latlong("latlong_moon_rls", 256);
    lalotorv("lalotorv_earth", 4);
    lalotorv("lalotorv_earth_fixed", 4);
    lalotorv("lalotorv_moon", 4);
    rp_r("rptor_earth", true, 0);
    rp_r("rptor_moon", true, 4);
    rp_r("rtorp_earth", false, 0);
    rp_r("rtorp_moon", false, 4);
    tff("tff_earth_entry", 12);
    tff("tff_earth_high", 12);
    tff("tff_earth_hyp", 12);
    tff("tff_moon", 12);
    lspos_cm("lspos_cm_t0", 0);
    lspos_cm("lspos_cm_t1", 0);
    lspos_cm("lspos_cm_t2", 0);
    lunvel_cm("lunvel_cm", 0);
    incorp2("incorp2_6d_earth", 0, 0);
    incorp2("incorp2_9d_earth", 0, 0);
    incorp2("incorp2_6d_moon", 0, 0);

    if (!oracle_load("nav_aux_lm"))
    {
        (void) printf("oracle_nav_aux: SKIP LM (case files not found)\n");

        return (oracle_finish("oracle_nav_aux"));
    }

    agc_state_init(AGC_VEHICLE_LM);
    lspos_lm("lspos_lm_t0", 2);
    lspos_lm("lspos_lm_t1", 2);
    lspos_lm("lspos_lm_t2", 2);

    return (oracle_finish("oracle_nav_aux"));
}
